// 収録弾の順序リスト（App.jsxのフィルター順と合わせる）
const packOrder = [
  'BSTH001 東方靈異伝','BSTH002 東方封魔録','BSTH003 東方夢時空','BSTH004 東方幻想郷','BSTH005 東方怪綺談','BSTH01 東方紅魔郷','BSTH02 東方妖々夢','BSTH02.5 東方萃夢想','BSTH02.7 夢違科学世紀','BSTH03 東方永夜抄','BSTH04 東方花映塚','BSTH04.5 東方文花帖','BSTH05 東方風神録','BSTH05.5 東方緋想天','BSTH06 東方地霊殿','BSTH07 東方星蓮船','BSTH07.8 妖精大戦争','BSTH08 東方神霊廟','BSTH08.5 東方心綺楼','BSTH09 東方輝針城','BSTH09.2 東方求聞史記','BSTH10 東方紺珠伝','BSTH10.5 東方憑依花','BSTH11 東方天空璋','BSSA01 ソードアートオンライン-アリシゼーション-公理協会編','BSGE01 ゴッドイーター','BSAZ01 アルドノア・ゼロ-地球-','BSAZ02 アルドノア・ゼロ-火星-','BSAZ03 アルドノア・ゼロ(Re+)','BSSG01 戦姫絶唱シンフォギア-切歌＆調-','BSSG02 戦姫絶唱シンフォギア-追加パック-','BSFT01 フェアリーテイル-ルーシィ・ハートフィリア-','BSES01 ８６-エイティシックス-','BSSL01 俺だけレベルアップな件','BSRK01 るろうに剣心','BSTS01 転生したらスライムだった件','BSDB01 ドラゴンボールZ','BSLH01 英雄伝説 軌跡シリーズ','BSKB01 星のカービィシリーズ-メタナイト編-'
];

function getPackRank(card) {
  // ダブルフェイスはfront優先
  const pack = card.isDoubleSided && card.front ? card.front.pack : card.pack;
  const idx = packOrder.indexOf(pack);
  return idx === -1 ? 999 : idx;
}

function getCardNumberParts(card) {
  // ダブルフェイスはfront優先
  const num = card.isDoubleSided && card.front ? card.front.cardNumber : card.cardNumber;
  if (!num) return { alpha: '', num: 99999 };
  // 例: 'BSTH01-C01' → ['C', 1]
  const afterDash = num.split('-')[1] || '';
  const m = afterDash.match(/^([A-Z]+)(\d+)/i);
  if (m) {
    return { alpha: m[1], num: parseInt(m[2], 10) };
  }
  // 例外は末尾に
  return { alpha: afterDash, num: 99999 };
}

cardData.sort((a, b) => {
  const packA = getPackRank(a);
  const packB = getPackRank(b);
  if (packA !== packB) return packA - packB;
  const aParts = getCardNumberParts(a);
  const bParts = getCardNumberParts(b);
  if (aParts.alpha !== bParts.alpha) {
    return aParts.alpha.localeCompare(bParts.alpha);
  }
  return aParts.num - bParts.num;
});

const versionedCardData = cardData.map(applyVersionToCard);

export default versionedCardData;
